mapper.select:
select CM04_COMPANY, CM04_FACTORY, CM04_CODE, CM04_NAME, CM04_GBN, CM04_RMK, CM04_TABLE, CM04_INDTE, CM04_UPDTE, CM04_REG_ID, cm05_company, cm05_factory, cm05_code, cm05_value, cm05_name, cm05_seq, TO_CHAR(CM05_INDTE, 'YYYY-MM-DD HH24:MI') AS CM05_INDTE, TO_CHAR(cm05_updte, 'YYYY-MM-DD HH24:MI') AS CM05_UPDTE, CM05_INDTE, cm05_reg_id, cm05_lock from tb_cm_04,tb_cm_05 where cm04_company = cm05_company and cm04_factory = cm05_factory and cm04_code = cm05_code and cm04_company = #{company} and cm04_factory = #{factory}
and cm05_code = #{code}
and cm05_lock = #{lock}
and cm05_value = #{gbnCcp}
and cm05_lock = #{lock}
and cm05_value != #{gbn}
order by cm05_code,cm05_seq
